(()=>{document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".collapse-summary").forEach(e=>{const t=e.querySelector(".summary-text"),n=e.querySelector(".toggle-summary"),s=t.classList.contains("collapsed");s&&t.classList.remove("collapsed");const o=t.scrollHeight;s&&t.classList.add("collapsed");const i=t.clientHeight;if(o>i)n.style.display="inline-block";else{t.classList.remove("collapsed");return}function a(){if(window.Filterizr&&typeof window.Filterizr.refresh=="function"){const e=window.Filterizr.getInstance(".container-filter");e?.refresh();return}window.dispatchEvent(new Event("resize"))}n.addEventListener("click",()=>{const e=t.classList.toggle("collapsed");n.textContent=e?"Read More":"Read Less",e||t.scrollIntoView({block:"nearest",behavior:"smooth"}),setTimeout(a,0)})})})})()